import {facilitatorHistory,facilitatorLabel} from './facilitation.mjs';
export class FacilitationPresentation{
 constructor(controller){this.c=controller;this.observer=new MutationObserver(()=>{if(this.queued)return;this.queued=true;queueMicrotask(()=>{this.queued=false;this.draw();});});this.observer.observe(document.body,{subtree:true,childList:true});}
 history(records){const ws=this.c.workspace,name=id=>ws.participants.find(p=>p.id===id)?.name||'Participant',d=document.createElement('dialog');d.className='facilitator-history';const title=document.createElement('h2');title.textContent='Contribution history';d.append(title);for(const r of records){const p=document.createElement('p');p.textContent=`${new Date(r.at).toLocaleString()} · ${name(r.participantId)} · ${r.method==='direct'?(r.draftId?`Approved directly; entered by ${name(r.enteredBy)}`:'Edited directly'):r.method==='verbal'?`Verbal approval recorded by ${name(r.operatorId)}`:`Entered by ${name(r.operatorId)} at the participant’s direction`} · saved version ${r.revision}`;d.append(p);}const close=document.createElement('button');close.textContent='Close';close.onclick=()=>d.close();d.append(close);d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();}
 badge(host,records,{node=false}={}){const label=facilitatorLabel(this.c.workspace,records),old=host.querySelector(':scope > .facilitator-badge');if(!label){old?.remove();return;}const key=records.map(r=>r.id).join(',');if(old?.dataset.receipts===key&&old.textContent===label)return;old?.remove();const b=document.createElement(host.matches('button')?'span':'button');if(b.tagName==='BUTTON')b.type='button';b.className='facilitator-badge'+(node?' facilitator-node-badge':'');b.dataset.receipts=key;b.textContent=label;b.title='View who entered and approved this contribution';if(b.tagName==='BUTTON')b.onclick=e=>{e.stopPropagation();this.history(records);};host.append(b);}
 draw(){const ws=this.c.workspace;if(!ws?.facilitationHistory?.length){for(const b of document.querySelectorAll('.facilitator-badge'))b.remove();return;}
  const discussionRecords=id=>facilitatorHistory(ws,{kind:'discussion',id});
  for(const card of document.querySelectorAll('.node[data-id],.node[data-node-id]')){const id=card.dataset.nodeId||card.dataset.id,mapId=card.dataset.mapId||this.c.activeMapId,related=new Set(ws.discussions.filter(r=>r.target?.type==='node'&&r.target.mapId===mapId&&r.target.nodeId===id).map(r=>r.id));const records=ws.facilitationHistory.filter(r=>r.kind==='map'&&r.recordId===mapId&&r.nodes.includes(id)||r.kind==='discussion'&&related.has(r.recordId));this.badge(card,records,{node:true});}
  for(const el of document.querySelectorAll('[data-entry],[data-dispute],[data-response],[data-dialogue-entry],[data-standstill-id]')){if(el.namespaceURI!=='http://www.w3.org/1999/xhtml')continue;const id=el.dataset.entry||el.dataset.dispute||el.dataset.response||el.dataset.dialogueEntry||el.dataset.standstillId;const ids=new Set([id,...ws.discussions.filter(r=>r.kind==='standstill'&&r.target?.entryId===id).map(r=>r.id)]);this.badge(el,ws.facilitationHistory.filter(r=>r.kind==='discussion'&&ids.has(r.recordId)));}
  const d=this.c.discussion;if(d?.viewId&&!d.host.hidden&&!d.host.dataset.standstillId)this.badge(d.host,discussionRecords(d.viewId));
 }
}
